import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), m = (int) nextLong();
        long k = nextLong();
        int[] values = new int[n];
        int answer = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) answer = Math.max(answer, values[i] = (int) nextLong()); // a lone center
        int[] eu = new int[m], ev = new int[m], deg = new int[n + 1];
        for (int i = 0; i < m; i++) {
            eu[i] = (int) nextLong();
            ev[i] = (int) nextLong();
            // Only positive neighbours can help a star.
            if (values[ev[i]] > 0) deg[eu[i]]++;
            if (values[eu[i]] > 0) deg[ev[i]]++;
        }
        int[] start = new int[n + 1];
        for (int i = 0; i < n; i++) start[i + 1] = start[i] + deg[i];
        int[] fill = Arrays.copyOf(start, n), weight = new int[start[n]];
        for (int i = 0; i < m; i++) {
            if (values[ev[i]] > 0) weight[fill[eu[i]]++] = values[ev[i]];
            if (values[eu[i]] > 0) weight[fill[ev[i]]++] = values[eu[i]];
        }
        for (int c = 0; c < n; c++) {
            // Sort ascending and take the k largest from the end.
            Arrays.sort(weight, start[c], start[c + 1]);
            int sum = values[c];
            for (int i = start[c + 1] - 1, taken = 0; i >= start[c] && taken < k; i--, taken++) sum += weight[i];
            answer = Math.max(answer, sum);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, m, k := int(nextInt()), int(nextInt()), nextInt()
	values := make([]int64, n)
	for i := range values {
		values[i] = nextInt()
	}
	// Only positive neighbours can help a star, so keep just their weights per center.
	neighbors := make([][]int64, n)
	for i := 0; i < m; i++ {
		u, v := nextInt(), nextInt()
		if values[v] > 0 {
			neighbors[u] = append(neighbors[u], values[v])
		}
		if values[u] > 0 {
			neighbors[v] = append(neighbors[v], values[u])
		}
	}
	answer := slices.Max(values) // a lone center
	for c := 0; c < n; c++ {
		list := neighbors[c]
		slices.Sort(list)
		sum := values[c]
		// Take the k largest from the end of the ascending list.
		for i, taken := len(list)-1, int64(0); i >= 0 && taken < k; i, taken = i-1, taken+1 {
			sum += list[i]
		}
		answer = max(answer, sum)
	}
	fmt.Println(answer)
}
